+/* ── Reset & tokens ── */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --bg:           #0f1117;
+  --surface:      #1a1d27;
+  --surface-2:    #232636;
+  --border:       #2e3250;
+  --border-focus: #6c7fff;
+  --text:         #e2e4f0;
+  --text-muted:   #8b90aa;
+  --accent:       #6c7fff;
+  --accent-hover: #8a94ff;
+  --error:        #ff6b6b;
+  --error-bg:     #2a1a1a;
+  --success:      #4caf82;
+  --success-bg:   #0e2a1f;
+  --required:     #ff9d6b;
+}
+
+/* ── Base ── */
+html { font-size: 100%; }
+
+body {
+  background: var(--bg);
+  color: var(--text);
+  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
+  font-size: 1rem;
+  line-height: 1.6;
+  min-height: 100vh;
+  display: flex;
+  flex-direction: column;
+}
+
+/* ── Skip link ── */
+.skip-link {
+  position: absolute;
+  top: -9999px;
+  left: 0;
+  background: var(--accent);
+  color: #fff;
+  padding: 0.5rem 1rem;
+  border-radius: 0 0 0.25rem 0;
+  font-weight: 600;
+  z-index: 100;
+  text-decoration: none;
+}
+.skip-link:focus {
+  top: 0;
+  outline: 3px solid #fff;
+  outline-offset: 2px;
+}
+
+/* ── Header ── */
+.site-header {
+  background: var(--surface);
+  border-bottom: 1px solid var(--border);
+  padding: 0.875rem 1.5rem;
+  display: flex;
+  align-items: center;
+  gap: 0.625rem;
+}
+.site-logo { font-size: 1.25rem; }
+.site-name  { font-size: 1rem; font-weight: 600; letter-spacing: 0.03em; color: var(--text); }
+
+/* ── Main layout ── */
+main {
+  flex: 1;
+  display: flex;
+  justify-content: center;
+  align-items: flex-start;
+  padding: 2.5rem 1rem 3rem;
+}
+
+/* ── Form card ── */
+.form-card {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: 0.75rem;
+  padding: 2.5rem 2rem;
+  width: 100%;
+  max-width: 520px;
+}
+
+.form-card h1 {
+  font-size: 1.5rem;
+  font-weight: 700;
+  margin-bottom: 0.5rem;
+  color: var(--text);
+}
+
+.form-intro {
+  color: var(--text-muted);
+  margin-bottom: 1.25rem;
+  font-size: 0.9375rem;
+}
+
+.required-legend {
+  font-size: 0.875rem;
+  color: var(--text-muted);
+  margin-bottom: 1.75rem;
+}
+.required-legend .required-marker,
+.required-marker {
+  color: var(--required);
+  font-weight: 700;
+  margin-left: 0.1em;
+}
+
+/* ── Form fields ── */
+.form-field {
+  display: flex;
+  flex-direction: column;
+  gap: 0.375rem;
+  margin-bottom: 1.5rem;
+}
+
+label {
+  font-size: 0.9375rem;
+  font-weight: 600;
+  color: var(--text);
+}
+
+.optional-label {
+  font-weight: 400;
+  color: var(--text-muted);
+  font-size: 0.875rem;
+}
+
+input {
+  background: var(--surface-2);
+  border: 1.5px solid var(--border);
+  border-radius: 0.4rem;
+  color: var(--text);
+  font-size: 1rem;
+  padding: 0.625rem 0.875rem;
+  width: 100%;
+  transition: border-color 0.15s, box-shadow 0.15s;
+  outline: none;
+  /* prevent system styling on autofill */
+  -webkit-text-fill-color: var(--text);
+}
+
+input:-webkit-autofill,
+input:-webkit-autofill:focus {
+  -webkit-box-shadow: 0 0 0 1000px var(--surface-2) inset;
+  -webkit-text-fill-color: var(--text);
+}
+
+input:focus {
+  border-color: var(--border-focus);
+  box-shadow: 0 0 0 3px color-mix(in srgb, var(--border-focus) 30%, transparent);
+}
+
+input[aria-invalid="true"] {
+  border-color: var(--error);
+  background: var(--error-bg);
+}
+
+input[aria-invalid="true"]:focus {
+  box-shadow: 0 0 0 3px color-mix(in srgb, var(--error) 25%, transparent);
+}
+
+/* ── Help & error text ── */
+.field-help {
+  font-size: 0.8125rem;
+  color: var(--text-muted);
+  line-height: 1.5;
+}
+
+.field-error {
+  font-size: 0.875rem;
+  color: var(--error);
+  font-weight: 500;
+  line-height: 1.4;
+}
+
+/* ── Submit button ── */
+.submit-btn {
+  margin-top: 0.5rem;
+  width: 100%;
+  background: var(--accent);
+  border: none;
+  border-radius: 0.4rem;
+  color: #fff;
+  cursor: pointer;
+  font-size: 1rem;
+  font-weight: 600;
+  padding: 0.75rem 1.5rem;
+  transition: background 0.15s, box-shadow 0.15s;
+}
+.submit-btn:hover { background: var(--accent-hover); }
+.submit-btn:focus-visible {
+  outline: 3px solid var(--border-focus);
+  outline-offset: 3px;
+}
+
+/* ── Success message ── */
+.success-message {
+  display: flex;
+  align-items: flex-start;
+  gap: 0.875rem;
+  background: var(--success-bg);
+  border: 1px solid var(--success);
+  border-radius: 0.5rem;
+  color: var(--text);
+  margin-top: 1.5rem;
+  padding: 1rem 1.25rem;
+}
+.success-message[hidden] { display: none; }
+.success-icon {
+  color: var(--success);
+  font-size: 1.25rem;
+  line-height: 1.4;
+  flex-shrink: 0;
+}
+.success-message strong {
+  display: block;
+  color: var(--success);
+  margin-bottom: 0.25rem;
+}
+
+/* ── Screen-reader only utility ── */
+.sr-only {
+  clip: rect(0 0 0 0);
+  clip-path: inset(50%);
+  height: 1px;
+  overflow: hidden;
+  position: absolute;
+  white-space: nowrap;
+  width: 1px;
+}
+
+/* ── Forced colours (high-contrast mode) ── */
+@media (forced-colors: active) {
+  input { border: 2px solid ButtonText; }
+  input:focus { outline: 3px solid Highlight; }
+  .field-error { color: LinkText; }
+  .submit-btn {
+    background: ButtonFace;
+    color: ButtonText;
+    border: 2px solid ButtonText;
+    forced-color-adjust: none;
+  }
+}
+
+/* ── Reduced motion ── */
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after { transition: none !important; }
+}
+
+/* ── Reflow: 320 px viewport ── */
+@media (max-width: 400px) {
+  .form-card {
+    padding: 1.5rem 1rem;
+    border-radius: 0;
+    border-left: none;
+    border-right: none;
+  }
+}
+
')

