 *    #submit-status live region announces the result to screen readers.
 */

(function () {
  "use strict";

  /* ── Field descriptors ── */
  const FIELDS = [
    {
      id: "full-name",
      errorId: "full-name-error",
      required: true,
      validate(value) {
        if (!value.trim()) return "Error: Full name is required.";
        return null;
      },
    },
    {
      id: "email",
      errorId: "email-error",
      required: true,
      validate(value) {
        if (!value.trim()) return "Error: Email address is required.";
        /* Basic RFC-aligned email pattern */
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
          return "Error: Enter a valid email address, e.g. name@example.com.";
        }
        return null;
      },
    },
    {
      id: "phone",
      errorId: "phone-error",
      required: false,
      validate(value) {
        if (!value.trim()) return null; /* optional — empty is fine */
        /*
         * Accept common formats:
         *   +1 (555) 000-0000   +44 20 7946 0958
         *   555-000-0000        5550000000
         * At least 7 digits required.
         */
        const digitsOnly = value.replace(/\D/g, "");
        if (digitsOnly.length < 7 || !/^[+\d\s()./-]{7,20}$/.test(value.trim())) {
          return "Error: Enter a valid phone number, e.g. +1 (555) 000-0000.";
        }
        return null;
      },
    },
  ];

  /* ── DOM refs ── */
  const form          = document.getElementById("contact-form");
  const submitStatus  = document.getElementById("submit-status");
  const successPanel  = document.getElementById("success-message");

  /* ── Helpers ── */

  function getInput(fieldId) {
    return document.getElementById(fieldId);
  }

  function getErrorEl(errorId) {
    return document.getElementById(errorId);
  }

  /**
   * Show or clear the inline error for a field.
   * @param {object} field  - FIELDS descriptor
   * @param {string|null} message - null to clear
   */
  function setFieldError(field, message) {
    const input   = getInput(field.id);
    const errorEl = getErrorEl(field.errorId);

    if (message) {
      errorEl.textContent = message;
      errorEl.hidden      = false;
      input.setAttribute("aria-invalid", "true");
    } else {
      errorEl.hidden      = true;
      errorEl.textContent = "";
      input.setAttribute("aria-invalid", "false");
    }
  }

  /**
   * Validate a single field and update its error state.
   * @returns {string|null} error message, or null if valid
   */
  function validateField(field) {
    const input   = getInput(field.id);
    const message = field.validate(input.value);
    setFieldError(field, message);
    return message;
  }

  /* ── Per-field blur validation (inline feedback while filling form) ── */
  FIELDS.forEach((field) => {
    const input = getInput(field.id);

    input.addEventListener("blur", () => {
      validateField(field);
    });

    /* Clear error as soon as the user starts correcting the field */
    input.addEventListener("input", () => {
      const errorEl = getErrorEl(field.errorId);
      if (!errorEl.hidden) {
        validateField(field);
      }
    });
  });

  /* ── Submit handler ── */
  form.addEventListener("submit", (event) => {
    event.preventDefault();

    const errors = FIELDS.map((field) => ({
      field,
      message: validateField(field),
    })).filter((r) => r.message !== null);

    if (errors.length > 0) {
      /* Move focus to the first invalid field */
      getInput(errors[0].field.id).focus();

      /* Announce total error count to screen readers */
      submitStatus.textContent = "";
      /* Force re-announcement by resetting then setting (next microtask) */
      requestAnimationFrame(() => {
        submitStatus.textContent =
          errors.length === 1
            ? "There is 1 error in the form. Please review and correct it."
            : `There are ${errors.length} errors in the form. Please review and correct them.`;
      });
      return;
    }

    /* ── Simulate successful submission ── */
    form.hidden = true;
    successPanel.hidden = false;

    /* Announce success to screen readers via polite live region */
    submitStatus.textContent =
      "Message sent. We'll reply to your email within 1 to 2 business days.";
  });
})();
